package com.hotelhaven.service;
import com.hotelhaven.dto.BookingRequest; import com.hotelhaven.model.*; import com.hotelhaven.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.temporal.ChronoUnit; import java.util.List;
@Service public class BookingService { private final BookingRepository bookings; private final RoomRepository rooms; private final UserRepository users; public BookingService(BookingRepository b,RoomRepository r,UserRepository u){bookings=b;rooms=r;users=u;}
@Transactional public Booking create(String email,BookingRequest req){if(!req.checkOut().isAfter(req.checkIn())) throw new IllegalArgumentException("Check-out must be after check-in."); Room room=rooms.findById(req.roomId()).orElseThrow(()->new IllegalArgumentException("Room not found.")); if(req.guests()>room.getCapacity()) throw new IllegalArgumentException("Guest count exceeds room capacity."); long nights=ChronoUnit.DAYS.between(req.checkIn(),req.checkOut()); User user=users.findByEmailIgnoreCase(email).orElseThrow(); return bookings.save(new Booking(user,room,req.checkIn(),req.checkOut(),req.guests(),room.getPrice()*nights));}
public List<Booking> history(String email){return bookings.findByUserOrderByCheckInDesc(users.findByEmailIgnoreCase(email).orElseThrow());}}
